int main(void) {
    char *p = malloc(4096 * 4);
    strcpy(p, "touch");                      /* force the page to exist */
    uint64_t va = (uint64_t)p + 0x123;
    printf("virtual address   0x%016lx\n", va);
    printf("bits 47..39 (PGD) %lu\n", (va >> 39) & 0x1ff);
    printf("bits 38..30 (PUD) %lu\n", (va >> 30) & 0x1ff);
    printf("bits 29..21 (PMD) %lu\n", (va >> 21) & 0x1ff);
    printf("bits 20..12 (PTE) %lu\n", (va >> 12) & 0x1ff);
    printf("bits 11..0  (off) 0x%lx\n", va & 0xfff);
    int fd = open("/proc/self/pagemap", O_RDONLY);
    uint64_t e;
    pread(fd, &e, 8, (va >> 12) * 8);
    printf("pagemap entry     0x%016lx\n", e);
    uint64_t pfn = e & ((1ULL << 55) - 1);
    printf("present=%lu swapped=%lu soft-dirty=%lu exclusive=%lu pfn=0x%lx\n",
           (unsigned long)((e >> 63) & 1), (unsigned long)((e >> 62) & 1),
           (unsigned long)((e >> 55) & 1), (unsigned long)((e >> 56) & 1), (unsigned long)pfn);
    printf("physical address  0x%lx\n", (unsigned long)((pfn << 12) | (va & 0xfff)));
    return 0;
}

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/resource.h>
#include <sys/wait.h>

static long minf(void) {
    struct rusage r; getrusage(RUSAGE_SELF, &r); return r.ru_minflt;
}
static long majf(void) {
    struct rusage r; getrusage(RUSAGE_SELF, &r); return r.ru_majflt;
}

int main(void) {
    const size_t MB = 1 << 20, PG = 4096;
    long m0, M0;

    size_t n = 64 * MB;
    char *a = mmap(NULL, n, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    m0 = minf();
    printf("anonymous 64 MiB mapped, no page touched: +%ld minor\n",
           minf() - m0);
    m0 = minf();
    for (size_t i = 0; i < n; i += PG) a[i] = 1;
    printf("write one byte per page (%zu pages):      +%ld minor\n",
           n / PG, minf() - m0);
    m0 = minf();
    for (size_t i = 0; i < n; i += PG) a[i] = 2;
    printf("write the same pages again:               +%ld minor\n",
           minf() - m0);

    /* file-backed mapping */
    size_t fn = 32 * MB;
    int fd = open("/tmp/osw_o3/data.bin", O_RDWR | O_CREAT | O_TRUNC, 0644);
    char *buf = malloc(MB);
    memset(buf, 'x', MB);
    for (int i = 0; i < 32; i++) write(fd, buf, MB);
    fsync(fd);
    posix_fadvise(fd, 0, 0, POSIX_FADV_DONTNEED);   /* evict from page cache */
    char *f = mmap(NULL, fn, PROT_READ, MAP_PRIVATE, fd, 0);
    long sum = 0;
    m0 = minf(); M0 = majf();
    for (size_t i = 0; i < fn; i += PG) sum += f[i];
    printf("file 32 MiB, cache cold, read each page:  +%ld minor, +%ld major\n",
           minf() - m0, majf() - M0);
    munmap(f, fn);
    f = mmap(NULL, fn, PROT_READ, MAP_PRIVATE, fd, 0);
    m0 = minf(); M0 = majf();
    for (size_t i = 0; i < fn; i += PG) sum += f[i];
    printf("file 32 MiB, cache warm, read each page:  +%ld minor, +%ld major\n",
           minf() - m0, majf() - M0);
    munmap(f, fn);
    posix_fadvise(fd, 0, 0, POSIX_FADV_DONTNEED);
    f = mmap(NULL, fn, PROT_READ, MAP_PRIVATE, fd, 0);
    madvise(f, fn, MADV_RANDOM);              /* no readahead, no fault-around */
    m0 = minf(); M0 = majf();
    for (size_t i = 0; i < 1000; i++)
        sum += f[((i * 7919) % 8192) * PG];
    printf("file cold, MADV_RANDOM, 1000 pages:       +%ld minor, +%ld major\n",
           minf() - m0, majf() - M0);
    fflush(stdout);

    /* copy-on-write after fork */
    pid_t pid = fork();
    if (pid == 0) {
        long c0 = minf();
        for (size_t i = 0; i < 16 * MB; i += PG) a[i] = 3;      /* 4096 pages */
        printf("child writes 4096 inherited pages (COW):  +%ld minor\n",
               minf() - c0);
        c0 = minf();
        for (size_t i = 32 * MB; i < 48 * MB; i += PG) sum += a[i];  /* read */
        printf("child reads 4096 inherited pages:         +%ld minor\n",
               minf() - c0);
        fflush(stdout); _exit(0);
    }
    wait(NULL);
    return sum == 42;
}

