static long anon_huge_kb(void) {
    FILE *f = fopen("/proc/self/smaps_rollup", "r"); char l[128]; long v = -1;
    while (fgets(l, sizeof l, f)) if (sscanf(l, "AnonHugePages: %ld kB", &v) == 1) break;
    fclose(f); return v;
}

static void run(int huge) {
    size_t n = 32UL << 20;
    size_t two = 2UL << 20;
    char *raw = mmap(NULL, n + two, PROT_READ | PROT_WRITE,
                     MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    char *p = (char *)(((unsigned long)raw + two - 1) & ~(two - 1));   /* 2 MiB aligned */
    if (huge) madvise(p, n, MADV_HUGEPAGE);
    struct rusage a, b; getrusage(RUSAGE_SELF, &a);
    struct timespec t0, t1; clock_gettime(CLOCK_MONOTONIC, &t0);
    for (size_t i = 0; i < n; i += 4096) p[i] = 1;
    clock_gettime(CLOCK_MONOTONIC, &t1); getrusage(RUSAGE_SELF, &b);
    double ms = (t1.tv_sec - t0.tv_sec) * 1e3 + (t1.tv_nsec - t0.tv_nsec) / 1e6;
    printf("%-22s: %6ld faults, AnonHugePages %6ld kB, first touch %.1f ms\n",
           huge ? "MADV_HUGEPAGE" : "default (madvise mode)",
           b.ru_minflt - a.ru_minflt, anon_huge_kb(), ms);
}

int main(void) { run(0); run(1); return 0; }

def fifo(refs, n):
    frames, faults = [], 0
    for r in refs:
        if r not in frames:
            faults += 1
            if len(frames) == n:
                frames.pop(0)                    # oldest arrival leaves
            frames.append(r)
    return faults


def lru(refs, n):
    frames, faults = [], 0                       # list ordered from least to most recent
    for r in refs:
        if r in frames:
            frames.remove(r)
        else:
            faults += 1
            if len(frames) == n:
                frames.pop(0)                    # least recently used leaves
        frames.append(r)
    return faults


def clock(refs, n):
    frames, bits, hand, faults = [None] * n, [0] * n, 0, 0
    for r in refs:
        if r in frames:
            bits[frames.index(r)] = 1            # hardware sets the reference bit
            continue
        faults += 1
        while bits[hand]:                        # second chance: clear and move on
            bits[hand] = 0
            hand = (hand + 1) % n
        frames[hand], bits[hand] = r, 1
        hand = (hand + 1) % n
    return faults


def opt(refs, n):
    frames, faults = [], 0
    for i, r in enumerate(refs):
        if r in frames:
            continue
        faults += 1
        if len(frames) == n:
            future = refs[i + 1:]
            # evict the page whose next use is farthest away (never used again: infinity)
            far = lambda p: future.index(p) if p in future else len(refs) + 1
            frames.remove(max(frames, key=far))
        frames.append(r)
    return faults


