static void report(const char *tag, int fd, size_t size) {
    void *m = mmap(NULL, size, PROT_READ, MAP_SHARED, fd, 0);
    size_t pages = size / 4096, n = 0;
    unsigned char *vec = malloc(pages);
    mincore(m, size, vec);
    for (size_t i = 0; i < pages; i++) n += vec[i] & 1;
    printf("%-30s %5zu of %zu pages in the page cache\n", tag, n, pages);
    munmap(m, size);
    free(vec);
}

int main(void) {
    size_t size = 64UL << 20;
    int fd = open("/tmp/osw_o3/fc.bin", O_RDWR | O_CREAT | O_TRUNC, 0644);
    char *buf = calloc(1, 1 << 20);
    for (int i = 0; i < 64; i++) if (write(fd, buf, 1 << 20) < 0) return 1;
    fsync(fd);
    report("after writing 64 MiB:", fd, size);
    posix_fadvise(fd, 0, 0, POSIX_FADV_DONTNEED);
    report("after POSIX_FADV_DONTNEED:", fd, size);
    for (int i = 0; i < 16; i++) if (pread(fd, buf, 1 << 20, (off_t)i << 20) < 0) return 1;
    report("after reading the first 16 MiB:", fd, size);
    unlink("/tmp/osw_o3/fc.bin");
    return 0;
}

