static void show(const char *tag) {
    FILE *f = fopen("/proc/meminfo", "r"); char l[128];
    while (fgets(l, sizeof l, f))
        if (!strncmp(l, "Committed_AS", 12)) printf("%-22s %s", tag, l);
    fclose(f);
}

int main(void) {
    size_t gib[] = {1, 4, 16, 64};
    show("start");
    for (int i = 0; i < 4; i++) {
        void *p = malloc(gib[i] << 30);                 /* reserved, never touched */
        printf("malloc(%2zu GiB) -> %s\n", gib[i], p ? "success" : "NULL");
        if (p) show("after malloc");
        /* deliberately not freed and not written: no page is ever allocated */
    }
    return 0;
}

