import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

public class NativeHog {
    public static void main(String[] args) throws Exception {
        List<ByteBuffer> keep = new ArrayList<>();
        Runtime rt = Runtime.getRuntime();
        for (int i = 1; i <= 12; i++) {                       // at most 192 MiB of direct memory
            ByteBuffer b = ByteBuffer.allocateDirect(16 << 20);
            for (int p = 0; p < b.capacity(); p += 4096) b.put(p, (byte) 1);
            keep.add(b);
            long heapUsedMb = (rt.totalMemory() - rt.freeMemory()) >> 20;
            System.out.printf("direct=%3d MiB  heapUsed=%2d MiB  heapMax=%d MiB%n",
                    i * 16, heapUsedMb, rt.maxMemory() >> 20);
            System.out.flush();
        }
        System.out.println("survived");
    }
}

import java.nio.ByteBuffer;
import java.util.Arrays;

public class Idle {
    public static void main(String[] a) throws Exception {
        byte[][] keep = new byte[20][];
        for (int i = 0; i < 20; i++) {                // 100 MiB of live data
            keep[i] = new byte[5 << 20];
            Arrays.fill(keep[i], (byte) 1);
        }
        ByteBuffer d = ByteBuffer.allocateDirect(16 << 20);   // 16 MiB outside the heap
        for (int i = 0; i < d.capacity(); i += 4096) d.put(i, (byte) 1);
        System.out.println("pid " + ProcessHandle.current().pid());
        Thread.sleep(Long.parseLong(a[0]));           // argument in milliseconds
        System.out.println(keep.length + d.capacity());
    }
}

import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;

public class OomKinds {
    static class Loader extends ClassLoader {
        final byte[] bytes;
        Loader(byte[] bytes) { this.bytes = bytes; }
        Class<?> make() { return defineClass("Dummy", bytes, 0, bytes.length); }
    }

    public static void main(String[] args) throws Exception {
        List<Object> keep = new ArrayList<>();
        try {
            switch (args[0]) {
                case "heap" -> { while (true) keep.add(new byte[1 << 20]); }
                case "direct" -> { while (true) keep.add(ByteBuffer.allocateDirect(1 << 20)); }
                case "meta" -> {
                    byte[] bytes = Files.readAllBytes(Path.of("Dummy.class"));
                    while (true) keep.add(new Loader(bytes).make());   // one class per loader
                }
                case "threads" -> {
                    CountDownLatch never = new CountDownLatch(1);
                    while (true) {
                        Thread t = new Thread(() -> {
                            try { never.await(); } catch (InterruptedException e) { }
                        });
                        t.setDaemon(true);
                        t.start();
                        keep.add(t);
                    }
                }
                default -> throw new IllegalArgumentException(args[0]);
            }
        } catch (OutOfMemoryError e) {
            int n = keep.size();
            keep.clear();
            System.out.println("caught: " + e);
            System.out.println("objects/threads created: " + n);
        }
    }
}

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class LeakDemo {
    record Profile(String userId, byte[] avatar) { }
    // Unbounded cache: entries are added on every request and never evicted.
    static final Map<String, Profile> CACHE = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        System.out.println("pid " + ProcessHandle.current().pid());
        long id = 0;
        long end = System.currentTimeMillis() + Long.parseLong(args[0]);
        while (System.currentTimeMillis() < end) {
            String key = "user-" + (id++);
            CACHE.put(key, new Profile(key, new byte[4096]));
            Thread.sleep(1);   // about 700-900 requests per second
        }
        System.out.println("entries " + CACHE.size());
    }
}
